function validate(input) {
  const [{ Drivers = [], Vehicles = [], Trips = [] }] = input;
  const drivers = new Set(), vehicles = new Set(), trips = new Set();
  for (const [id, , , , accidents] of Drivers) {
    if (id === null) return 'Every driver needs a driver_id.';
    if (drivers.has(id)) return `driver_id ${id} appears twice in Drivers.`;
    drivers.add(id);
    if (accidents === null || accidents < 0) return `Driver ${id} needs a non-negative accidents count.`;
  }
  for (const [id, driver, , fuel] of Vehicles) {
    if (id === null) return 'Every vehicle needs a vehicle_id.';
    if (vehicles.has(id)) return `vehicle_id ${id} appears twice in Vehicles.`;
    vehicles.add(id);
    if (!drivers.has(driver)) return `Vehicle ${id} names driver ${driver}, who is not in Drivers.`;
    if (fuel === null) return `Vehicle ${id} needs a fuel_type.`;
  }
  for (const [id, vehicle, distance, , rating] of Trips) {
    if (id === null) return 'Every trip needs a trip_id.';
    if (trips.has(id)) return `trip_id ${id} appears twice in Trips.`;
    trips.add(id);
    if (!vehicles.has(vehicle)) return `Trip ${id} uses vehicle ${vehicle}, which is not in Vehicles.`;
    if (distance === null || distance < 0) return `Trip ${id} needs a non-negative distance.`;
    if (rating === null || rating < 1 || rating > 5) return `Trip ${id} needs a rating from 1 to 5.`;
  }
  return null;
}

