function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const small = size === 'small';
  const names = ['Alice', 'Bob', 'Charlie', 'Dana', 'Eve', 'Farid', 'Grace', 'Hiro'];
  const models = ['Sedan', 'SUV', 'Coupe', 'Van', 'Hatchback'];
  const fuels = small ? ['Gasoline', 'Electric', 'Diesel'] : ['Diesel', 'Electric', 'Gasoline', 'Hybrid', 'Hydrogen'];
  const Drivers = [], Vehicles = [], Trips = [];
  const driverCount = small ? pick(5) : 300;
  for (let i = 0; i < driverCount; i++) {
    // Small cases keep accidents in 0..2 so the last tie-break is often reached.
    Drivers.push([small ? 1 + 2 * i + pick(2) : i + 1, names[pick(names.length)], 21 + pick(45), pick(31), small ? pick(3) : pick(6)]);
  }
  const vehicleCount = Drivers.length === 0 ? 0 : small ? 1 + pick(4) : 450;
  for (let i = 0; i < vehicleCount; i++) {
    Vehicles.push([100 + i, Drivers[pick(Drivers.length)][0], models[pick(models.length)], fuels[pick(fuels.length)], 1000 * (1 + pick(90))]);
  }
  if (small) {
    // Few distances and high ratings make equal ratings and equal distances common.
    const tripCount = Vehicles.length === 0 ? 0 : pick(9);
    for (let i = 0; i < tripCount; i++) Trips.push([201 + i, Vehicles[pick(Vehicles.length)][0], 10 * (1 + pick(5)), 10 * (1 + pick(6)), 3 + pick(3)]);
  } else {
    for (const [vehicle] of Vehicles) for (let k = pick(7); k > 0 && Trips.length < 2000; k--) Trips.push([Trips.length + 1, vehicle, 1 + pick(500), 5 + pick(116), 1 + pick(5)]);
  }
  for (const rows of [Drivers, Vehicles, Trips]) for (let i = rows.length - 1; i > 0; i--) { const j = pick(i + 1); [rows[i], rows[j]] = [rows[j], rows[i]]; }
  return [{ Drivers, Vehicles, Trips }];
}
